// Couple quizzes: the four modes and the Polish question bank. Shared by the
// Worker (picks the questions, keeps the answers hidden until both answered,
// scores) and the browser (shows them).
//
// A question is plain data: { id, text, options?, self?, guess? }. A session
// stores full copies of its questions, so questions from another source (for
// example generated by AI later, with `source: 'ai'`) can be played without
// changing the game: they only have to pass `validQuestion`.
export const MODES = {
  zgodnosc: { name: 'Quiz zgodności', short: 'Zgodność', desc: 'Odpowiadacie na te same pytania. Ile razy myślicie tak samo?', count: 7, kind: 'match', icon: 'hearts' },
  znasz: { name: 'Jak dobrze mnie znasz?', short: 'Znasz mnie?', desc: 'Na zmianę: jedno odpowiada o sobie, drugie zgaduje.', count: 6, kind: 'guess', icon: 'think' },
  wybierasz: { name: 'Co wybierasz?', short: 'Co wybierasz?', desc: 'Szybkie „to czy to”. Dziesięć wyborów, zobaczcie, gdzie się zgadzacie.', count: 10, kind: 'match', icon: 'split' },
  pary: { name: 'Pytania dla par', short: 'Rozmowa', desc: 'Pytania do rozmowy. Każde pisze krótko, odpowiedzi odsłaniacie razem.', count: 5, kind: 'open', icon: 'chat' },
};
export const MAX_OPEN = 160; // characters in an open answer

const Q = (mode, list) => list.map(([id, text, options, extra]) => ({ id: `${mode}-${id}`, mode, text, ...(options ? { options } : {}), ...(extra || {}) }));

