export const BANK_BY_ID = Object.fromEntries(BANK.map(q => [q.id, q]));

// A question from any source is playable when it has a text, and for every
// non-open mode 2-4 short options. Texts are kept short for the phone screen.
export function validQuestion(q, mode) {
  if (!q || typeof q.text !== 'string' || !q.text.trim() || q.text.length > 140) return false;
  if (MODES[mode]?.kind === 'open') return !q.options;
  return Array.isArray(q.options) && q.options.length >= 2 && q.options.length <= 4 && q.options.every(o => typeof o === 'string' && o.length > 0 && o.length <= 48);
}
// Pick `count` questions for a new session, preferring ones not played recently.
export function pick(mode, recent = [], rnd = Math.random) {
  const pool = BANK.filter(q => q.mode === mode && validQuestion(q, mode));
  const fresh = pool.filter(q => !recent.includes(q.id)), use = fresh.length >= MODES[mode].count ? fresh : pool;
  const a = [...use];
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a.slice(0, MODES[mode].count);
}
// In "Jak dobrze mnie znasz?" the person asked about alternates: question 0 is
// about the session's creator, question 1 about the other one, and so on.
export const aboutSlot = (session, idx) => (idx % 2 === 0 ? session.by : 3 - session.by);
// Score: matches (zgodność, wybierasz) or correct guesses (znasz); open
// questions have no score.
export function score(mode, answers) {
  const kind = MODES[mode]?.kind;
  if (kind === 'open') return null;
  const both = answers.filter(a => a[1] != null && a[2] != null);
  return { hits: both.filter(a => a[1] === a[2]).length, of: answers.length };
}
